declare(strict_types=1);

namespace OCA\GrafanaSync\Tests\Unit;

use OCA\GrafanaSync\Vendor\Symfony\Component\Yaml\Yaml;
use PHPUnit\Framework\TestCase;

/**
 * The one third-party library this app ships, and the two ways shipping it goes wrong.
 *
 * `lib/Vendor/` is generated by `composer install` (Strauss, from `composer.json`) and
 * never committed. A checkout that skipped the install fails the first test here rather
 * than every YAML test at once; a Strauss run that copied without prefixing fails the
 * second, which is the failure that would only show up on an instance where another app
 * also ships Symfony.
 */
final class VendorTest extends TestCase {
	public function testThePrefixedYamlLoads(): void {
		$parsed = Yaml::parse('a: {}', Yaml::PARSE_OBJECT_FOR_MAP);

		self::assertInstanceOf(\stdClass::class, $parsed);
		self::assertEquals(new \stdClass(), $parsed->a);
	}

	public function testNoUnprefixedSymfonyIsShipped(): void {
		$root = dirname(__DIR__, 2) . '/lib/Vendor';
		self::assertDirectoryExists($root);

		$leaks = [];
		$files = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root, \FilesystemIterator::SKIP_DOTS));
		foreach ($files as $file) {
			if ($file->getExtension() === 'php' && preg_match('/^namespace Symfony\\\\/m', (string)file_get_contents($file->getPathname()))) {
				$leaks[] = substr($file->getPathname(), strlen($root) + 1);
			}
		}
		self::assertSame([], $leaks, 'Symfony classes shipped without the OCA\\GrafanaSync\\Vendor prefix');
	}
}
